def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return clamp_step(b - a)

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def pos_from(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return default

    sx, sy = pos_from(observation.get("self_position", (0, 0)))
    ox, oy = pos_from(observation.get("opponent_position", (sx, sy)))
    env = observation.get("environment_name", "resource_collection")

    width = observation.get("grid_width", 0)
    height = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [step_toward(sx, ox), step_toward(sy, oy)]
        corners = [(0, 0)]
        if height:
            corners.append((0, height - 1))
        if width:
            corners.append((width - 1, 0))
        if width and height:
            corners.append((width - 1, height - 1))
        target = None
        best = None
        for c in corners:
            score = manhattan(c, (ox, oy))
            if best is None or score > best:
                best = score
                target = c
        if target is None:
            return [0, 0]
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        target = None
        for item in targets:
            p = pos_from(item, None)
            if p is None:
                continue
            score = manhattan((sx, sy), p)
            if best is None or score < best:
                best = score
                target = p
        if target is None:
            # If no explicit target, move toward opponent to pressure territory.
            return [step_toward(sx, ox), step_toward(sy, oy)]
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    target = None
    for item in resources:
        p = pos_from(item, None)
        if p is None:
            continue
        score = manhattan((sx, sy), p)
        if best is None or score < best:
            best = score
            target = p
    if target is not None:
        return [step_toward(sx, target[0]), step_toward(sy, target[1])]

    # Fallback: move toward opponent if no resources are visible.
    return [step_toward(sx, ox), step_toward(sy, oy)]

